"""Transfer two disjoint zodiac panel word-box sets onto the common Yale canvas."""
import hashlib
import json
from pathlib import Path

import cv2
import numpy as np
from PIL import Image, ImageDraw
from scipy.interpolate import RBFInterpolator
from scipy.spatial import cKDTree


ROOT = Path(__file__).resolve().parent
REGIONS = {
    "f72v3": [840, 220, 3580, 3360],
    "f72v2": [3485, 380, 5800, 3150],
}
SEED = 724204


def source_image(name):
    return Image.open(ROOT / "assets" / name / "reference.jpg").convert("L")


def target_image(full, name):
    crop = full.crop(REGIONS[name])
    readout = np.array(crop.convert("L"))
    scale = 1600 / max(crop.size)
    overview = cv2.resize(readout, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA)
    magnification = [crop.width / overview.shape[1], crop.height / overview.shape[0]]
    return crop, overview, magnification


def sift_descriptor_matches(source, target):
    sift = cv2.SIFT_create(nfeatures=6500, contrastThreshold=0.018)
    left, ld = sift.detectAndCompute(np.array(source), None)
    right, rd = sift.detectAndCompute(target, None)
    pairs = cv2.BFMatcher().knnMatch(ld, rd, k=2)
    matches = [a for a, b in pairs if a.distance < .72 * b.distance]
    return (np.float32([left[p.queryIdx].pt for p in matches]),
            np.float32([right[p.trainIdx].pt for p in matches]))


def transform(points, matrix):
    return cv2.perspectiveTransform(np.asarray(points, dtype=np.float64)[:, None, :], matrix)[:, 0]


def spatial_split(points, source_size):
    w, h = source_size
    cells = np.minimum((points * [4 / w, 4 / h]).astype(int), 3)
    groups = {}
    for i, cell in enumerate(cells):
        groups.setdefault(tuple(cell), []).append(i)
    train, test = [], []
    for cell, members in sorted(groups.items()):
        order = sorted(members, key=lambda k: hashlib.sha256(
            f"{SEED}:{cell}:{points[k][0]:.4f}:{points[k][1]:.4f}".encode()
        ).digest())
        for j, k in enumerate(order):
            (test if j % 4 == 0 else train).append(k)
    return np.array(train), np.array(test)


def warp_fit(source, target, group):
    if len(group) < 20:
        return None
    h, ransac = cv2.findHomography(source[group], target[group], cv2.RANSAC, 4.0)
    if h is None or ransac is None:
        return None
    base = transform(source[group], h)
    residual = target[group] - base
    tree = cKDTree(source[group])
    neighbors = tree.query(source[group], k=min(22, len(group)))[1]
    local = np.median(residual[neighbors], axis=1)
    near = np.linalg.norm(residual-local, axis=1) <= 3.0
    if sum(near) < 35:
        return h, None, int(ransac.sum()), group[near]
    smooth = RBFInterpolator(source[group][near], residual[near], smoothing=30.0, neighbors=42)
    return h, smooth, int(ransac.sum()), group[near]


def measure(source, target, src_name, target_name, magnification):
    a, b = sift_descriptor_matches(source, target)
    info = {"source_panel": src_name, "target_region": target_name, "descriptor_matches": len(a)}
    train, test = spatial_split(a, source.size)
    model = warp_fit(a, b, train)
    if model is None:
        return info, None
    H, warp, inliers, kept = model
    predicted = transform(a[test], H)
    initial = np.linalg.norm((predicted - b[test]) * magnification, axis=1)
    info.update({
        "train_matches": len(train), "withheld_matches": len(test), "train_ransac_inliers_count": inliers,
        "train_consistent_local_matches_count": int(len(kept)),
        "withheld_native_median_homography_px": float(np.median(initial)),
        "withheld_native_p90_homography_px": float(np.quantile(initial, .90)),
    })
    if warp is not None:
        error = np.linalg.norm((predicted + warp(a[test]) - b[test]) * magnification, axis=1)
        info.update({
            "withheld_native_median_px": float(np.median(error)),
            "withheld_native_p90_px": float(np.quantile(error, .90)),
            "withheld_native_within_10_px": float(np.mean(error <= 10)),
        })
    return info, (a, b, train, test)


def project_boxes(panel, fitted, scale, details):
    a, b, _, _ = fitted
    H, warp, _, kept = warp_fit(a, b, np.arange(len(a)))
    origin = np.asarray(REGIONS[panel][:2])
    if warp is None:
        raise ValueError((panel, details))
    lexicon, words = json.loads((ROOT / "assets" / panel / "boxes.json").read_text())
    projected = []
    for index, (reading_id, x, y, w, h) in enumerate(words):
        if not w or not h:
            continue
        corners = np.asarray([[x,y],[x+w,y],[x+w,y+h],[x,y+h]], dtype=float)
        native = (transform(corners, H) + warp(corners)) * scale + origin
        projected.append({
            "box_index": index, "lexeme": lexicon[reading_id][0], "source_xywh": [x,y,w,h],
            "quad_native": native.round(2).tolist(),
            "bbox_native": [*native.min(axis=0).round(2), *native.max(axis=0).round(2)],
        })
    details["source_native_crop_xyxy"] = REGIONS[panel]
    details["registration_scale_per_axis"] = scale
    details["registered_box_count"] = len(projected)
    details["retained_dense_correspondence_count"] = int(len(kept))
    details["boxes"] = projected
    out = ROOT / "assets" / panel / "registration.json"
    out.write_text(json.dumps(details, indent=2) + "\n")


def main():
    cv2.setNumThreads(1)
    cv2.setRNGSeed(SEED)
    full = Image.open(ROOT / "yale-1006204.jpg").convert("RGB")
    crops = {name: target_image(full, name) for name in REGIONS}
    diagnostics = {}
    for name in REGIONS:
        source = source_image(name)
        diagnostics[name] = {}
        for candidate, (_, target, scale) in crops.items():
            result, match = measure(source, target, name, candidate, scale)
            diagnostics[name][candidate] = dict(result)
            if candidate == name and match is not None:
                project_boxes(name, match, scale, result)
    (ROOT / "registration-diagnostics.json").write_text(json.dumps(diagnostics, indent=2) + "\n")
    print(json.dumps(diagnostics, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.assemble_maps.py:
"""Merge word assignments, independently reviewed first-glyph anchors, and circle geometry."""
import hashlib
import json
import math
from pathlib import Path
from statistics import median

import numpy as np
from PIL import Image, ImageDraw


ROOT = Path(__file__).resolve().parent
WHEELS = {"f72v2": "native_right", "f72v3": "native_left"}
CANVAS = "https://collections.library.yale.edu/manifests/oid/2002046/canvas/1006204"


def load(relative):
    return json.loads((ROOT/relative).read_text())


def digest(relative):
    return hashlib.sha256((ROOT/relative).read_bytes()).hexdigest()


def bearing(xy, center):
    return math.degrees(math.atan2(xy[0]-center[0],center[1]-xy[1])) % 360


def difference(a,b):
    return (a - b + 180) % 360 - 180


def clock_value(text):
    h,m=map(int,text.split(":"))
    return (h % 12) * 30 + m / 2


def center_of_box(box):
    return [(box[0]+box[2])/2,(box[1]+box[3])/2]


def convert(proposal, read):
    if read.get("unresolved"):
        return None
    if "choice" in read:
        return proposal["candidates"][read["choice"]]["native_xy"]
    if "native_xy" in read:
        return read["native_xy"]
    board = read["board_xy"]
    offset = proposal["tile_origin_board_xy"]
    framing = proposal["card_crop_origin_xy"]
    return [
        origin+(b-off-frame)/proposal["scale"]
        for b,off,frame,origin in zip(board,offset,framing,proposal["crop_native_xyxy"][:2],strict=True)
    ]


def interband_ratio(point, ellipse):
    x,y = [a-b for a,b in zip(point,ellipse["center_xy"],strict=True)]
    phi=math.radians(ellipse["major_axis_clockwise_degrees_from_north_mod_180"])
    a=x*math.sin(phi)-y*math.cos(phi)
    b=x*math.cos(phi)+y*math.sin(phi)
    return math.hypot(a/ellipse["semimajor_px"], b/ellipse["semiminor_px"])


def by_panel(proposals, geometry, independent, adjudications):
    result={}
    for panel,orientation in WHEELS.items():
        review=load(f"{panel}-head-review.json")
        wheel=geometry["wheels"][orientation]
        center=wheel["rings"]["central_medallion_outer_rule"]["circle_fit"]["center_xy"]
        alternate=wheel["rings"]["outer_perimeter_outer_rule"]["ellipse_fit"]["center_xy"]
        interband=wheel["rings"]["interband_outer_rule"]["ellipse_fit"]
        labels={}
        assert len(review)==30
        for locus, proposal in proposals.items():
            if not locus.startswith(panel+"."):
                continue
            optical=review[locus]
            first_pass=convert(proposal,optical)
            chosen=adjudications.get(locus)
            anchor=chosen["after_second_review_native_xy"] if chosen else first_pass
            word_center=center_of_box(proposal["word_native_xyxy"])
            clock=clock_value(proposal["clock"])
            row={
                "ring":proposal["ring"],"coarse_zl_clock":proposal["clock"],
                "first_glyph_native_xy": None, "first_glyph_clockwise_degrees":None,
                "word_center_native_xy_diagnostic":[round(p,2) for p in word_center],
                "word_center_clockwise_degrees_diagnostic":round(bearing(word_center,center),2),
                "word_box_index_0_based":proposal["first_box_index"],
                "first_word_source_reading":proposal["indexed_words"][0],
                "manual_head_review":optical,
            }
            if chosen:
                row["adjudicated_head_review"]=chosen
            if anchor is not None:
                x0,y0,x1,y1=proposal["crop_native_xyxy"]
                assert x0<=anchor[0]<=x1 and y0<=anchor[1]<=y1,(locus,anchor,proposal["crop_native_xyxy"])
                theta=bearing(anchor,center)
                rel=interband_ratio(anchor,interband)
                row.update({
                    "first_glyph_native_xy":[round(p,2) for p in anchor],
                    "first_glyph_clockwise_degrees":round(theta,2),
                    "glyph_bearing_minus_coarse_zl_clock_deg":round(difference(theta,clock),2),
                    "alternate_perimeter_center_bearing_change_deg":round(
                        difference(bearing(anchor,alternate),theta),2
                    ),
                    "interband_ellipse_normalized_radius":round(rel,3),
                    "radial_position_close_to_separating_rule":abs(rel-1) < .065,
                })
                if locus in independent:
                    checks=independent[locus]
                    row["independent_rotated_spot_check"]=dict(checks, difference_native_px=round(
                        math.dist(first_pass,checks["native_first_glyph_xy"]),2
                    ))
            labels[locus]=row
        known=[row for row in labels.values() if row["first_glyph_native_xy"] is not None]
        deltas=[row["glyph_bearing_minus_coarse_zl_clock_deg"] for row in known]
        alt=[abs(row["alternate_perimeter_center_bearing_change_deg"]) for row in known]
        nmid=[row for row in known if (row["ring"]=="inner") != (row["interband_ellipse_normalized_radius"]<1)]
        result[panel]={
            "canvas":CANVAS,"position_on_native_canvas":orientation,"medallion_center_native_xy":center,
            "perimeter_center_native_xy_for_sensitivity":alternate,
            "counts":{
                "labels":len(labels),"outer":sum(v["ring"]=="outer" for v in labels.values()),
                "inner":sum(v["ring"]=="inner" for v in labels.values()),"native_heads_resolved":len(known),
            },
            "clock_comparison":{
                "median_signed_native_minus_coarse_deg":round(median(deltas),2),
                "median_absolute_native_minus_coarse_deg":round(median(abs(d) for d in deltas),2),
                "max_absolute_native_minus_coarse_deg":round(max(abs(d) for d in deltas),2),
                "n_more_than_20_deg":sum(abs(d)>20 for d in deltas),
                "max_shift_if_outer_perimeter_center_used_deg":round(max(alt),2),
            },
            "independent_spot_check_differences_px":{
                locus: row["independent_rotated_spot_check"]["difference_native_px"]
                for locus,row in labels.items() if "independent_rotated_spot_check" in row
            },
            "near_band_geometry_disagreements":[
                key for key,value in labels.items() if value in nmid
            ],
            "loci":labels,
        }
    return result


def overlay(result):
    image=Image.open(ROOT/"yale-1006204.jpg").convert("RGB")
    ratio=1/3
    image=image.resize((round(image.width*ratio),round(image.height*ratio)),Image.Resampling.LANCZOS)
    draw=ImageDraw.Draw(image)
    for panel, values in result.items():
        cx,cy=[v*ratio for v in values["medallion_center_native_xy"]]
        draw.line((cx-7,cy,cx+7,cy),fill=(20,75,165),width=2)
        draw.line((cx,cy-7,cx,cy+7),fill=(20,75,165),width=2)
        for locus,row in values["loci"].items():
            native=row["first_glyph_native_xy"]
            if native is None:
                continue
            px,py=[v*ratio for v in native]
            ink=(200,48,10) if row["ring"]=="outer" else (20,73,173)
            draw.ellipse((px-3,py-3,px+3,py+3),outline=ink,width=1)
            draw.text((px+4,py-6),locus.split(".")[1],fill=ink)
    image.save(ROOT/"native-combined-map.jpg",quality=94)


def main():
    proposals=load("word-card-proposals.json")
    geometry=load("circle-geometry.json")
    independent=load("independent-rotated-spot-check.json")
    mapped=by_panel(proposals,geometry,independent,load("head-adjudication.json"))
    assert sum(row["counts"]["labels"] for row in mapped.values())==60
    overlay(mapped)
    (ROOT/"native-angle-maps.json").write_text(json.dumps(mapped,indent=2,ensure_ascii=False)+"\n")
    print(json.dumps({panel:{key:value for key,value in row.items() if key!="loci"}
                      for panel,row in mapped.items()},indent=2,ensure_ascii=False))


if __name__=="__main__":
    main()
